SET fertilizing_monthly_strategy_json = '{"reviewStatus":"unsupported","scopeLabel":"温带容器向日葵参考（长出真叶后的生长期）","coverageReason":"权威资料把向日葵施肥写成定植和真叶阶段等生育节点，未给出可稳定映射到月份的属级固定间隔；现有月份重复展示“长出真叶后”会制造重复施肥误解，暂不展示月度表。","baseIntervalDays":[30,60],"sourceRefs":[{"id":"umn-sunflower","name":"UMN Extension","url":"https://extension.umn.edu/gardening-minnesota/sunflowers","evidenceRef":"向日葵：长出数片真叶时追施一次通用缓释肥以促进生长和花朵"},{"id":"rhs-container-feeding","name":"RHS","url":"https://www.rhs.org.uk/garden-jobs/nutrition-feeding-plants","evidenceRef":"容器植物：生长期 April–September 液体肥；果蔬每两周；一年生草花夏季3–4次；避免9月后追肥"},{"id":"osu-sunflowers","name":"Oregon State University Extension","url":"https://extension.oregonstate.edu/catalog/em-9866-grow-your-own-sunflowers","evidenceRef":"容器向日葵可在定植时和长出两对真叶时分两次施肥"}],"notes":"保留基础属级施肥间隔；月度表改为未审核，用户应按定植和真叶阶段判断，不能把生育节点重复填入4至9月。","scopeType":"unknown","adjustmentMode":"none","publicNote":""}'
